// tb.v: random-stimulus testbench for CaseMux, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg [2:0] op = 3'd0;
    reg [7:0] a = 8'd0;
    reg [7:0] b = 8'd0;
    reg go = 1'b0;
    wire [7:0] y;
    wire flag;
    wire [1:0] z;
    wire [7:0] w;
    wire [1:0] phase;
    wire [7:0] osel;
    reg [19:0] stim [0:239];
    integer i;

    CaseMux dut (
        .clk(clk),
        .rst(rst),
        .op(op),
        .a(a),
        .b(b),
        .go(go),
        .y(y),
        .flag(flag),
        .z(z),
        .w(w),
        .phase(phase),
        .osel(osel)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {op, a, b, go} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h %h", i, y, flag, z, w, phase, osel);
            cycle_clk;
        end
        $finish;
    end
endmodule
